-- Migrate IC Review Level Five data INSERT INTO m_loan_decision_level (loan_decision_id, ic_review_level_id, level_number, note, is_signed, is_rejected, decision_on, decision_by, recommended_amount, term_frequency, term_period_frequency_enum, createdby_id, created_date, lastmodifiedby_id, lastmodified_date) SELECT ld.id, (SELECT id FROM m_ic_review_level_config WHERE level_number = 5), 5, ld.ic_review_decision_level_five_note, COALESCE(ld.is_ic_review_decision_level_five_signed, false), COALESCE(ld.is_reject_ic_review_decision_level_five, false), ld.ic_review_decision_level_five_on, ld.ic_review_decision_level_five_by, ld.ic_review_decision_level_five_recommended_amount, ld.ic_review_decision_level_five_term_frequency, ld.ic_review_decision_level_five_term_period_frequency_enum, ld.createdby_id, ld.created_date, ld.lastmodifiedby_id, ld.lastmodified_date FROM m_loan_decision ld WHERE EXISTS (SELECT 1 FROM m_ic_review_level_config WHERE level_number = 5) AND (ld.ic_review_decision_level_five_note IS NOT NULL OR ld.is_ic_review_decision_level_five_signed IS NOT NULL OR ld.is_reject_ic_review_decision_level_five IS NOT NULL OR ld.ic_review_decision_level_five_on IS NOT NULL);
